def icon(name: str, size: int = 16, cls: str = "", stroke: float = 1.75, title: str | None = None) -> Markup:
    """Icône : référence ``<use>`` vers la feuille d'icônes (``/icones.svg``, gardée en cache, voir
    ``web.py``) plutôt que son dessin recopié à chaque emploi. Le trait (couleur, extrémités) est dans la
    feuille ; l'épaisseur et le remplissage restent ici, pour qu'une règle CSS (étoile des favoris) ou
    ``stroke=`` puisse les changer."""
    if name not in ICONS:
        name = "hash"
    t = f"<title>{escape(title)}</title>" if title else ""
    return Markup(
        f'<svg class="ic {cls}" width="{size}" height="{size}" fill="none" stroke-width="{stroke}" '
        f'aria-hidden="true">{t}<use href="{adresse_icones()}#{name}"/></svg>'
    )


def state_icon(group: str, color: str | None = None, size: int = 14) -> Markup:
    color = color or STATE_GROUP_COLORS.get(group, "#a3a3a3")
    if group == "backlog":
        inner = f'<circle cx="12" cy="12" r="9" stroke="{color}" stroke-dasharray="3.2 3"/>'
    elif group == "unstarted":
        inner = f'<circle cx="12" cy="12" r="9" stroke="{color}"/>'
    elif group == "started":
        inner = (f'<circle cx="12" cy="12" r="9" stroke="{color}"/>'
                 f'<path d="M12 6.5a5.5 5.5 0 0 1 0 11z" fill="{color}" stroke="none"/>')
    elif group == "completed":
        inner = (f'<circle cx="12" cy="12" r="10" fill="{color}" stroke="none"/>'
                 '<path d="m7.5 12.5 3 3 6-6.5" stroke="#fff" stroke-width="2.4"/>')
    else:  # cancelled
        inner = (f'<circle cx="12" cy="12" r="10" fill="{color}" stroke="none"/>'
                 '<path d="m9 9 6 6M15 9l-6 6" stroke="#fff" stroke-width="2.4"/>')
    return Markup(
        f'<svg class="ic state-ic" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
        f'stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">{inner}</svg>'
    )


def priority_icon(priority: str, size: int = 14) -> Markup:
    color = PRIORITY_COLORS.get(priority, "#a3a3a3")
    if priority == "urgent":
        inner = (f'<rect x="2" y="2" width="20" height="20" rx="5" fill="{color}"/>'
                 '<path d="M12 6.5v7" stroke="#fff" stroke-width="2.6" stroke-linecap="round"/>'
                 '<circle cx="12" cy="17.3" r="1.5" fill="#fff"/>')
    elif priority == "none":
        inner = (f'<rect x="2.5" y="2.5" width="19" height="19" rx="5" fill="none" stroke="{color}" '
                 'stroke-width="1.6" stroke-dasharray="3 2.4"/><path d="M8 12h8" stroke="'
                 f'{color}" stroke-width="2" stroke-linecap="round"/>')
    else:
        filled = {"high": 3, "medium": 2, "low": 1}.get(priority, 0)
        bars = [(3.5, 14, 6.5), (10.25, 9, 11.5), (17, 4, 16.5)]
        inner = ""
        for idx, (x, y, h) in enumerate(bars):
            op = "1" if idx < filled else "0.25"
            inner += f'<rect x="{x}" y="{y}" width="4" height="{h}" rx="1.2" fill="{color}" opacity="{op}"/>'
    return Markup(
        f'<svg class="ic prio-ic" width="{size}" height="{size}" viewBox="0 0 24 24" aria-hidden="true">{inner}</svg>'
    )
